def transform(g):
    g=[row[:] for row in g]; H=len(g); W=len(g[0])
    # find horizontal 5-lines and vertical 5-lines (maximal runs length>=2)
    hlines=[]  # (row, c0, c1)
    for r in range(H):
        c=0
        while c<W:
            if g[r][c]==5:
                c0=c
                while c<W and g[r][c]==5: c+=1
                if c-c0>=2: hlines.append((r,c0,c-1))
            else: c+=1
    vlines=[]
    for c in range(W):
        r=0
        while r<H:
            if g[r][c]==5:
                r0=r
                while r<H and g[r][c]==5: r+=1
                if r-r0>=2: vlines.append((c,r0,r-1))
            else: r+=1
    # collect colored cells
    colored={(r,c) for r in range(H) for c in range(W) if g[r][c] not in (0,5)}
    for (r,c0,c1) in hlines:
        cells=[(rr,cc) for (rr,cc) in colored if c0-1<=cc<=c1+1 and rr!=r]
        if not cells: continue
        rows=sorted({rr for rr,cc in cells})
        # strip perpendicular: replicate each row's colors along the line span
        for rr in rows:
            pat=[g[rr][cc] for cc in range(c0,c1+1) if g[rr][cc] not in (0,5)]
            if len(pat)==c1-c0+1:  # strip perpendicular fills across (cells just off line)
                pass
        # perpendicular case: strip below/above line, each strip row has one color at col c0-? 
        for rr in rows:
            src=[(rr,cc) for cc in range(W) if g[rr][cc] not in (0,5)]
            if len(src)==1:
                col=val=src[0][1], g[rr][src[0][1]]
                for cc in range(c0,c1+1):
                    if g[rr][cc]==0: g[rr][cc]=val[1]
        for rr,cc in cells: colored.discard((rr,cc))
    for (c,r0,r1) in vlines:
        cells=[(rr,cc) for (rr,cc) in colored if r0-1<=rr<=r1+1 and cc!=c]
        if not cells: continue
        rows=sorted({rr for rr,cc in cells})
        pat=[g[rr][cc] for rr in rows for cc in range(W) if (rr,cc) in cells and cc>c]
        if rows==list(range(r0,r1+1)):
            # parallel block spanning line: tile along line from top
            p=[[g[rr][cc] for cc in range(min(cc2 for _,cc2 in cells), max(cc2 for _,cc2 in cells)+1)] for rr in rows]
            P=len(p)
            for i,rr in enumerate(range(r0,r1+1)):
                for j,cc in enumerate(range(min(cc2 for _,cc2 in cells), max(cc2 for _,cc2 in cells)+1)):
                    g[rr][cc]=p[i%P][j]
        for rr,cc in cells: colored.discard((rr,cc))
    return g

def t2(g):
    g=[row[:] for row in g]; H=len(g); W=len(g[0])
    # vertical 5-lines
    vlines=[]
    for c in range(W):
        r=0
        while r<H:
            if g[r][c]==5:
                r0=r
                while r<H and g[r][c]==5: r+=1
                if r-r0>=2: vlines.append((c,r0,r-1))
            else: r+=1
    colored=[(r,c) for r in range(H) for c in range(W) if g[r][c] not in (0,5)]
    # demo2 style: block parallel to a vertical line
    for (c,r0,r1) in vlines:
        cells=[(rr,cc) for (rr,cc) in colored if cc>c]
        if not cells: continue
        rows=sorted({rr for rr,cc in cells})
        if rows==list(range(r0,r1+1)) and all(cc>c for rr,cc in cells):
            cmin=min(cc for _,cc in cells); cmax=max(cc for _,cc in cells)
            p=[[g[rr][cc] for cc in range(cmin,cmax+1)] for rr in rows]
            P=len(p)
            for i,rr in enumerate(range(r0,r1+1)):
                for j,cc in enumerate(range(cmin,cmax+1)):
                    g[rr][cc]=p[i%P][j]
    # horizontal 5-lines with perpendicular strip
    for r in range(H):
        cc2=0
        while cc2<W:
            if g[r][cc2]==5:
                c0=cc2
                while cc2<W and g[r][cc2]==5: cc2+=1
                if cc2-c0<2: continue
                for rr in range(H):
                    if rr==r: continue
                    src=[x for x in range(W) if g[rr][x] not in (0,5)]
                    if len(src)==1 and g[rr][src[0]]!=0:
                        val=g[rr][src[0]]
                        for x in range(c0,cc2):
                            if g[rr][x]==0: g[rr][x]=val
            else: cc2+=1
    return g

