def transform(g):
    g=[row[:] for row in g]; H=len(g); W=len(g[0])
    # maximal 5-lines
    lines=[]  # ('h', r, c0, c1) or ('v', c, r0, r1)
    for r in range(H):
        c=0
        while c<W:
            if g[r][c]==5:
                c0=c
                while c<W and g[r][c]==5: c+=1
                if c-c0>=2: lines.append(('h',r,c0,c-1))
            else: c+=1
    for c in range(W):
        r=0
        while r<H:
            if g[r][c]==5:
                r0=r
                while r<H and g[r][c]==5: r+=1
                if r-r0>=2: lines.append(('v',c,r0,r-1))
            else: r+=1
    # connected components of colored cells
    colored={(r,c) for r in range(H) for c in range(W) if g[r][c] not in (0,5)}
    comps=[]
    seen=set()
    for cell in colored:
        if cell in seen: continue
        stack=[cell]; comp=set()
        while stack:
            cur=stack.pop()
            if cur in seen or cur not in colored: continue
            seen.add(cur); comp.add(cur)
            r,c=cur
            for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                if (r+dr,c+dc) in colored: stack.append((r+dr,c+dc))
        comps.append(comp)
    out=[row[:] for row in g]
    for comp in comps:
        rs=[r for r,c in comp]; cs=[c for r,c in comp]
        rmin,rmax,cmin,cmax=min(rs),max(rs),min(cs),max(cs)
        # find attaching line: adjacent (orthogonally) to a 5-cell of a line
        best=None
        for (o,a0,a1,a2) in lines:
            if o=='h':
                r,c0,c1=a0,a1,a2
                if cmin>=c0-1 and cmax<=c1+1:
                    if rmin==r+1 or rmax==r-1: best=(o,a0,a1,a2)
            else:
                c,r0,r1=a0,a1,a2
                if rmin>=r0-1 and rmax<=r1+1:
                    if cmin==c+1 or cmax==c-1: best=(o,a0,a1,a2)
        if not best: continue
        o,a0,a1,a2=best
        if o=='h':
            r,c0,c1=a0,a1,a2  # t=col, p=row
            tspan=(c0,c1); trange=(cmin,cmax); prange=(rmin,rmax)
            ht=trange[1]-trange[0]+1
            for rr in range(prange[0],prange[1]+1):
                for cc in range(tspan[0],tspan[1]+1):
                    src_t=trange[0]+(cc-trange[0])%ht
                    out[rr][cc]=g[rr][src_t]
        else:
            c,r0,r1=a0,a1,a2  # t=row, p=col
            tspan=(r0,r1); trange=(rmin,rmax); prange=(cmin,cmax)
            ht=trange[1]-trange[0]+1
            for rr in range(tspan[0],tspan[1]+1):
                for cc in range(prange[0],prange[1]+1):
                    src_t=trange[0]+(rr-trange[0])%ht
                    out[rr][cc]=g[src_t][cc]
    return out

